export async function createBranchIfNotExists(
  repoFullName: string,
  branchName: string,
  baseBranch: string,
  accessToken: string,
): Promise<boolean> {
  const exists = await checkBranchExists(repoFullName, branchName, accessToken)
  if (exists) return false

  const [owner, repo] = repoFullName.split("/")
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${accessToken}`,
  }

  // Get base branch SHA
  const baseResponse = await fetch(
    `${GITHUB_API}/repos/${owner}/${repo}/branches/${encodeURIComponent(baseBranch)}`,
    { headers },
  )

  if (!baseResponse.ok) {
    throw new Error(`Base branch '${baseBranch}' not found: ${baseResponse.status}`)
  }
  const baseData = await baseResponse.json<{ commit: { sha: string } }>()

  // Create branch ref
  const refResponse = await fetch(`${GITHUB_API}/repos/${owner}/${repo}/git/refs`, {
    method: "POST",
    headers: { ...headers, "Content-Type": "application/json" },
    body: JSON.stringify({
      ref: `refs/heads/${branchName}`,
      sha: baseData.commit.sha,
    }),
  })

  if (!refResponse.ok) {
    const error = await refResponse.text()
    // 422 with "Reference already exists" means a concurrent request created it, which is fine
    if (refResponse.status === 422 && error.includes("Reference already exists")) {
      return false
    }
    throw new Error(`Failed to create branch: ${refResponse.status} - ${error}`)
  }

  return true
}

/**
 * Generate a random comment ID (8 hex characters)
 */
export function generateCommentId(): string {
  const array = new Uint8Array(4)
  crypto.getRandomValues(array)
  return Array.from(array, (b) => b.toString(16).padStart(2, "0")).join("")
}

