const body = await c.req.json<{
  title: string
  body?: string
  branch_name?: string
  branch_action?: "create" | "link"
  base?: string
  status?: TrailStatus
  assignees?: string[]
  labels?: string[]
  priority?: TrailPriority
}>()

if (!body.title?.trim()) {
  return c.json({ error: "Title is required" }, 400)
}
if (body.branch_action !== undefined && !["create", "link"].includes(body.branch_action)) {
  return c.json({ error: "branch_action must be 'create' or 'link'" }, 400)
}

// Default to 'create' so the web UI's "base → new-branch" flow keeps
// working. API clients that deliver their own branch (the CLI pushes the
// branch before calling us) pass 'link' to opt out of base-tip backfill.
const branchAction: "create" | "link" = body.branch_action === "link" ? "link" : "create"

let branchCreated = false
let branchLinked = false
let installationToken: string | null = null

if (body.branch_name && hasWritePermission && githubInstallationId) {
  installationToken = await getInstallationToken(
    githubInstallationId,
    appCreds,
    c.env.ENTIRE_CACHE,
  )

  if (branchAction === "link") {
    // Link-only intent: NEVER anchor a backing branch at the base tip.
    // If the branch was never delivered to the remote, creating it at
    // base would produce a trail whose branch is empty/diverged from the
    // caller's actual work — the silent drift this guard prevents. Refuse
    // instead, so the caller can push the branch (or create an unlinked
    // trail) rather than unknowingly tracking a phantom branch.
    const exists = await checkBranchExists(repoFullName, body.branch_name, installationToken)
    if (exists === false) {
      return c.json(
        {
          error: `Branch "${body.branch_name}" was not found on the remote. Push the branch before creating the trail, or omit branch_name to create an unlinked trail.`,
        },
        400,
      )
    }
    // exists === true links the delivered branch. exists === null (a
    // transient GitHub error, not a definitive 404) still links rather
    // than failing creation outright, since link mode never backfills.
    branchLinked = true
  } else {
    branchCreated = await createBranchIfNotExists(
      repoFullName,
      body.branch_name,
      base,
      installationToken,
    )
    branchLinked = true
  }
}

